<template>
  <div class="mobile-page"><div class="mobile-head"><b>皖企通</b><span>粮食主体填报</span><el-tag size="small" type="success">离线可用</el-tag></div><el-steps :active="active" simple finish-status="success"><el-step title="年度计划"/><el-step title="种植意向"/><el-step title="地块确认"/></el-steps><div class="form-card"><h3>2026 年度粮食生产计划</h3><el-form label-position="top"><el-form-item label="经营主体"><el-input v-model="form.subjectName"/></el-form-item><el-form-item label="年度计划面积（亩）"><el-input-number v-model="form.planArea" :min="0" style="width:100%"/></el-form-item><el-form-item label="种植意向"><el-checkbox-group v-model="form.crops"><el-checkbox label="wheat">小麦</el-checkbox><el-checkbox label="rice">水稻</el-checkbox><el-checkbox label="corn">玉米</el-checkbox><el-checkbox label="soybean">大豆</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="各作物面积（亩）"><div class="crop-inputs"><el-input-number v-model="form.wheat" controls-position="right" placeholder="小麦"/><el-input-number v-model="form.rice" controls-position="right" placeholder="水稻"/><el-input-number v-model="form.corn" controls-position="right" placeholder="玉米"/></div></el-form-item><el-form-item label="预计播种时间"><el-date-picker v-model="form.sowDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="历史对比"><div class="compare"><span>去年计划 980 亩</span><el-tag type="success">预计增长 {{ growth }}%</el-tag></div></el-form-item><el-form-item label="关联地块"><el-input v-model="form.plots" placeholder="例如 PL-0007、PL-0009"/></el-form-item></el-form><el-alert title="提交后将自动匹配农技指导、农机调度和灾害预警服务" type="info" show-icon :closable="false"/><div class="actions"><el-button @click="saveOffline">离线保存</el-button><el-button @click="syncDrafts">同步离线记录（{{ offlineDrafts.length }}）</el-button><el-button type="primary" @click="submit">提交填报</el-button></div><el-alert v-if="offlineDrafts.length" :title="`离线草稿 ${offlineDrafts.length} 条，状态：${syncStatus}`" type="warning" show-icon :closable="false" style="margin-top:12px"/></div><div class="service-card"><b>农事服务推送</b><p>小麦播种技术指导 · 阜阳市农技推广中心</p><p>秋粮抢收农机调度 · 可预约 3 台收割机</p></div></div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { syncOfflineReports } from '@/api/gpm'
const active = ref(1)
const offlineDrafts = ref([])
const syncStatus = ref('待同步')
const offlineKey = 'gpm-offline-drafts'; const form = reactive({ subjectName: '旧县镇赵多种植大户', planArea: 1100, crops: ['wheat', 'corn'], wheat: 520, rice: 0, corn: 480, sowDate: '2026-10-05', plots: 'PL-0007、PL-0009' }); const growth = computed(() => Math.round((form.planArea / 980 - 1) * 100)); const saveOffline = () => { const drafts = JSON.parse(localStorage.getItem(offlineKey) || '[]'); drafts.push({ ...form, id: `LOCAL-${Date.now()}`, status: '待同步', savedAt: new Date().toLocaleString() }); localStorage.setItem(offlineKey, JSON.stringify(drafts)); offlineDrafts.value = drafts; syncStatus.value = '待同步'; ElMessage.success('已保存至离线填报箱，联网后可同步') }; const syncDrafts = async () => { if (!offlineDrafts.value.length) return ElMessage.info('暂无离线草稿'); syncStatus.value = '同步中'; const result = await syncOfflineReports(offlineDrafts.value.map(item => item.id)); if (result.success) { offlineDrafts.value = offlineDrafts.value.map(item => ({ ...item, status: '已同步' })); localStorage.setItem(offlineKey, JSON.stringify(offlineDrafts.value)); syncStatus.value = '已同步'; ElMessage.success(`已同步 ${result.count} 条离线记录`) } }; onMounted(() => { offlineDrafts.value = JSON.parse(localStorage.getItem(offlineKey) || '[]') }); const submit = () => { if (!form.subjectName || !form.planArea || !form.crops.length) return ElMessage.warning('请完善主体、面积和种植意向'); active.value = 3; ElMessage.success('主体填报已提交，等待乡镇核验') }
</script>
<style lang="scss" scoped>.mobile-page{max-width:520px;margin:0 auto;min-height:100%;background:#f5f7fa;padding:14px}.mobile-head{display:flex;align-items:center;gap:10px;background:#fff;padding:16px;border-radius:10px;color:#1f3c68;margin-bottom:12px}.mobile-head b{font-size:20px}.mobile-head span{flex:1}.form-card,.service-card{background:#fff;border-radius:10px;padding:16px;margin-top:12px}.form-card h3{margin:0 0 16px;color:#243b5a}.crop-inputs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.compare{display:flex;align-items:center;justify-content:space-between;width:100%;font-size:13px;color:#667085}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.service-card{color:#667085;font-size:13px}.service-card b{color:#243b5a;font-size:15px}.service-card p{margin:10px 0}</style>
